(@DepartmentID int,@EmployeeCount int,@TotalSalary decimal(12,2),@AvgSalary decimal(10,2),@MinSalary decimal(10,2),@MaxSalary decimal(10,2))SELECT
        @EmployeeCount = COUNT(*),
        @TotalSalary = ISNULL(SUM(Salary), 0),
        @AvgSalary = ISNULL(AVG(Salary), 0),
        @MinSalary = ISNULL(MIN(Salary), 0),
        @MaxSalary = ISNULL(MAX(Salary), 0)
    FROM dbo.Employees
    WHERE DepartmentID = @DepartmentID

(@EmployeeID int,@CurrentSalary decimal(10,2),@CurrentDeptID int,@EmpName nvarchar(201))SELECT @CurrentSalary = Salary, @CurrentDeptID = DepartmentID,
           @EmpName = FirstName + ' ' + LastName
    FROM dbo.Employees WHERE EmployeeID = @EmployeeID
